{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js"
  }
}
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { dirname, join, extname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { DatabaseSync } from 'node:sqlite';

const root = dirname(fileURLToPath(import.meta.url));
const db = new DatabaseSync(process.env.DB_PATH || join(root, 'workboard.sqlite'));
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
)`);
const projectColumns = db.prepare('PRAGMA table_info(projects)').all();
if (!projectColumns.some((column) => column.name === 'archived')) {
  db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0');
}
db.exec(`CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
)`);

const contentTypes = { '.html': 'text/html; charset=utf-8', '.css': 'text/css; charset=utf-8', '.js': 'text/javascript; charset=utf-8' };

async function readJson(request) {
  let body = '';
  for await (const chunk of request) body += chunk;
  return JSON.parse(body || '{}');
}

function sendJson(response, status, value) {
  response.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(value));
}

const server = createServer(async (request, response) => {
  const url = new URL(request.url, 'http://localhost');
  try {
    if (url.pathname === '/health' && request.method === 'GET') return sendJson(response, 200, { status: 'ok' });
    if (url.pathname === '/api/projects' && request.method === 'GET') {
      return sendJson(response, 200, db.prepare(`SELECT p.id, p.name, p.archived,
        COUNT(t.id) AS totalCount,
        COALESCE(SUM(CASE WHEN t.completed = 1 THEN 1 ELSE 0 END), 0) AS completedCount
        FROM projects p LEFT JOIN tasks t ON t.project_id = p.id
        GROUP BY p.id ORDER BY p.id`).all().map((project) => ({
          ...project, archived: Boolean(project.archived),
        })));
    }
    if (url.pathname === '/api/projects' && request.method === 'POST') {
      const body = await readJson(request);
      const name = typeof body.name === 'string' ? body.name.trim() : '';
      if (!name) return sendJson(response, 400, { error: 'Project name is required' });
      const result = db.prepare('INSERT INTO projects (name) VALUES (?)').run(name);
      return sendJson(response, 201, { id: Number(result.lastInsertRowid), name, archived: false, totalCount: 0, completedCount: 0 });
    }
    const projectRoute = url.pathname.match(/^\/api\/projects\/(\d+)$/);
    if (projectRoute && request.method === 'PATCH') {
      const id = Number(projectRoute[1]);
      const body = await readJson(request);
      if (typeof body.archived !== 'boolean') return sendJson(response, 400, { error: 'Archive state is required' });
      const result = db.prepare('UPDATE projects SET archived = ? WHERE id = ?').run(body.archived ? 1 : 0, id);
      if (!result.changes) return sendJson(response, 404, { error: 'Project not found' });
      return sendJson(response, 200, { id, archived: body.archived });
    }
    const taskRoute = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
    if (taskRoute) {
      const projectId = Number(taskRoute[1]);
      if (!db.prepare('SELECT id FROM projects WHERE id = ?').get(projectId)) {
        return sendJson(response, 404, { error: 'Project not found' });
      }
      if (!taskRoute[2] && request.method === 'GET') {
        const tasks = db.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE project_id = ? ORDER BY id').all(projectId);
        return sendJson(response, 200, tasks.map((task) => ({ ...task, completed: Boolean(task.completed) })));
      }
      if (!taskRoute[2] && request.method === 'POST') {
        if (db.prepare('SELECT archived FROM projects WHERE id = ?').get(projectId).archived) {
          return sendJson(response, 409, { error: 'Archived projects cannot accept tasks' });
        }
        const body = await readJson(request);
        const title = typeof body.title === 'string' ? body.title.trim() : '';
        if (!title) return sendJson(response, 400, { error: 'Task title is required' });
        const result = db.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)').run(projectId, title);
        return sendJson(response, 201, { id: Number(result.lastInsertRowid), projectId, title, completed: false });
      }
      if (taskRoute[2] && request.method === 'PATCH') {
        if (db.prepare('SELECT archived FROM projects WHERE id = ?').get(projectId).archived) {
          return sendJson(response, 409, { error: 'Archived project tasks cannot be changed' });
        }
        const taskId = Number(taskRoute[2]);
        const body = await readJson(request);
        if (typeof body.completed !== 'boolean') return sendJson(response, 400, { error: 'Completion state is required' });
        const result = db.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?').run(body.completed ? 1 : 0, taskId, projectId);
        if (!result.changes) return sendJson(response, 404, { error: 'Task not found' });
        return sendJson(response, 200, { id: taskId, projectId, completed: body.completed });
      }
      return sendJson(response, 405, { error: 'Method not allowed' });
    }
    if (url.pathname.startsWith('/api/')) return sendJson(response, 404, { error: 'Not found' });

    const relativePath = url.pathname === '/' || /^\/projects\/\d+\/?$/.test(url.pathname)
      ? 'index.html'
      : url.pathname.replace(/^\//, '');
    const filePath = join(root, 'public', relativePath);
    if (!filePath.startsWith(join(root, 'public'))) {
      response.writeHead(403).end();
      return;
    }
    const content = await readFile(filePath);
    response.writeHead(200, { 'content-type': contentTypes[extname(filePath)] || 'application/octet-stream' });
    response.end(content);
  } catch (error) {
    if (error instanceof SyntaxError) return sendJson(response, 400, { error: 'Invalid JSON' });
    if (error.code === 'ENOENT') return sendJson(response, 404, { error: 'Not found' });
    console.error(error);
    sendJson(response, 500, { error: 'Internal server error' });
  }
});

const port = Number(process.env.PORT || 8080);
server.listen(port, '0.0.0.0', () => console.log(`Workboard listening on ${port}`));
const content = document.querySelector('#content');

async function getProjects() {
  const response = await fetch('/api/projects');
  if (!response.ok) throw new Error('Could not load projects');
  return response.json();
}

function projectRow(project) {
  const row = document.createElement('article');
  row.className = 'project-row';
  row.dataset.testid = 'project-row';
  const name = document.createElement('span');
  name.textContent = project.name;
  const summary = document.createElement('span');
  summary.dataset.testid = 'project-summary';
  summary.textContent = `${project.completedCount}/${project.totalCount} completed`;
  const open = document.createElement('button');
  open.type = 'button';
  open.textContent = 'Open project';
  open.addEventListener('click', () => { window.location.href = `/projects/${project.id}`; });
  row.append(name, summary, open);
  const archive = document.createElement('button');
  archive.type = 'button';
  archive.textContent = project.archived ? 'Restore project' : 'Archive project';
  archive.addEventListener('click', async () => {
    const response = await fetch(`/api/projects/${project.id}`, {
      method: 'PATCH', headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ archived: !project.archived }),
    });
    if (!response.ok) { showError('Could not update project'); return; }
    await renderList();
  });
  row.append(archive);
  return row;
}

function showError(message) {
  const alert = document.createElement('p');
  alert.className = 'alert';
  alert.setAttribute('role', 'alert');
  alert.textContent = message;
  content.prepend(alert);
}

async function renderList() {
  content.replaceChildren();
  const heading = document.createElement('h1');
  heading.textContent = 'Workboard';
  const form = document.createElement('form');
  form.className = 'create-form';
  const label = document.createElement('label');
  label.htmlFor = 'project-name';
  label.textContent = 'Project name';
  const input = document.createElement('input');
  input.id = 'project-name';
  input.name = 'name';
  input.type = 'text';
  const submit = document.createElement('button');
  submit.type = 'submit';
  submit.textContent = 'Create project';
  form.append(label, input, submit);
  const list = document.createElement('div');
  list.className = 'project-list';
  const filterLabel = document.createElement('label');
  filterLabel.htmlFor = 'project-filter';
  filterLabel.textContent = 'Project filter';
  const filter = document.createElement('select');
  filter.id = 'project-filter';
  for (const value of ['Active', 'Archived']) {
    const option = document.createElement('option');
    option.value = value;
    option.textContent = value;
    filter.append(option);
  }
  content.append(heading, form, filterLabel, filter, list);
  let projects = await getProjects();
  function drawProjects() {
    list.replaceChildren();
    const archived = filter.value === 'Archived';
    for (const project of projects) if (project.archived === archived) list.append(projectRow(project));
  }
  filter.addEventListener('change', drawProjects);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    const name = input.value.trim();
    if (!name) {
      content.querySelector('[role="alert"]')?.remove();
      showError('Project name is required');
      input.focus();
      return;
    }
    const response = await fetch('/api/projects', {
      method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name }),
    });
    if (!response.ok) {
      const result = await response.json();
      showError(result.error || 'Could not create project');
      return;
    }
    const project = await response.json();
    content.querySelector('[role="alert"]')?.remove();
    projects.push(project);
    drawProjects();
    form.reset();
    input.focus();
  });
  drawProjects();
}

async function renderProject(id) {
  const projects = await getProjects();
  const project = projects.find((item) => String(item.id) === id);
  content.replaceChildren();
  const back = document.createElement('button');
  back.type = 'button';
  back.textContent = 'Projects';
  back.addEventListener('click', () => { window.location.href = '/'; });
  content.append(back);
  if (project) {
    if (project.archived) {
      const archivedMessage = document.createElement('p');
      archivedMessage.textContent = 'Archived project';
      content.append(archivedMessage);
    }
    const heading = document.createElement('h1');
    heading.textContent = project.name;
    content.append(heading);
    const form = document.createElement('form');
    form.className = 'create-form';
    const label = document.createElement('label');
    label.htmlFor = 'task-title';
    label.textContent = 'Task title';
    const input = document.createElement('input');
    input.id = 'task-title';
    input.name = 'title';
    input.type = 'text';
    const submit = document.createElement('button');
    submit.type = 'submit';
    submit.textContent = 'Create task';
    submit.disabled = project.archived;
    input.disabled = project.archived;
    form.append(label, input, submit);
    const filterLabel = document.createElement('label');
    filterLabel.htmlFor = 'task-filter';
    filterLabel.textContent = 'Task filter';
    const filter = document.createElement('select');
    filter.id = 'task-filter';
    for (const value of ['All', 'Open', 'Completed']) {
      const option = document.createElement('option');
      option.value = value;
      option.textContent = value;
      filter.append(option);
    }
    const list = document.createElement('div');
    list.className = 'task-list';
    const tasksResponse = await fetch(`/api/projects/${id}/tasks`);
    if (!tasksResponse.ok) throw new Error('Could not load tasks');
    let tasks = await tasksResponse.json();
    function drawTasks() {
      list.replaceChildren();
      for (const task of tasks) {
        if (filter.value === 'Open' && task.completed) continue;
        if (filter.value === 'Completed' && !task.completed) continue;
        const row = document.createElement('article');
        row.className = 'task-row';
        row.dataset.testid = 'task-row';
        const title = document.createElement('span');
        title.textContent = task.title;
        const checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.checked = task.completed;
        checkbox.disabled = project.archived;
        checkbox.setAttribute('aria-label', `Complete ${task.title}`);
        checkbox.addEventListener('change', async () => {
          const response = await fetch(`/api/projects/${id}/tasks/${task.id}`, {
            method: 'PATCH', headers: { 'content-type': 'application/json' },
            body: JSON.stringify({ completed: checkbox.checked }),
          });
          if (!response.ok) { checkbox.checked = task.completed; showError('Could not update task'); return; }
          task.completed = checkbox.checked;
          drawTasks();
        });
        row.append(title, checkbox);
        list.append(row);
      }
    }
    filter.addEventListener('change', drawTasks);
    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      const title = input.value.trim();
      if (!title) {
        content.querySelector('[role="alert"]')?.remove();
        showError('Task title is required');
        input.focus();
        return;
      }
      const response = await fetch(`/api/projects/${id}/tasks`, {
        method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title }),
      });
      if (!response.ok) { const result = await response.json(); showError(result.error || 'Could not create task'); return; }
      tasks.push(await response.json());
      content.querySelector('[role="alert"]')?.remove();
      form.reset();
      drawTasks();
      input.focus();
    });
    content.append(form, filterLabel, filter, list);
    drawTasks();
  } else {
    const alert = document.createElement('p');
    alert.setAttribute('role', 'alert');
    alert.textContent = 'Project not found';
    content.append(alert);
  }
}

const projectMatch = window.location.pathname.match(/^\/projects\/(\d+)\/?$/);
(projectMatch ? renderProject(projectMatch[1]) : renderList()).catch((error) => {
  console.error(error);
  showError('Could not load projects');
});
